mapper.select:
select vfp.finprod_id as finprodId, /** 资产代码 **/ vfp.finprod_abbr as finprodAbbr, /**资产名称**/ vfp.finprod_market_id as finprodMarketId, /**市场代码**/ type.type_1 as fundType, /** 资金类型 **/ vfp.ISSUER as issuer, /** 管理人 -发行人 **/ vfp.ccy as ccyCode, /** 币种 **/ vfp.idate as idate, /** 发现日 **/ vfp.CALENDAR_ID as calendarId, /** 交易日历 **/ vfp.bln_area as blnArea, /** 境内外 **/ vfp.trade_market as tradeMarket, /** 交易场所 **/ vfp.ISSUER as custodian, /** 托管人 **/ ext.pur_speed as purSpeed, /** 申购确认速度 **/ ext.red_speed as redSpeed, /** 赎回确认速度 **/ vfp.CAPI_INCOME_FEATURE as capiIncomeFeature, /** 本金收益特征 **/ rule.pay_cycle as payCycle, /** 付息频率 **/ '' as payDate, /** 付息日 **/
rule.END_TDAY_RULE endTdayRule, /*截止日营业日准则*/ rule.PAY_TDAY_RULE payTdayRule, /*支付日营业日准则*/ rule.CALC_RULE as calcRule /** 推算方式 **/ from FIN_PRODUCT vfp left join FIN_PRODUCT_TYPE type on vfp.finprod_id = type.finprod_id left join fin_CASH_PAY_RULE rule on vfp.finprod_id = rule.finprod_id left join FIN_PRODUCT_ADD ext on vfp.finprod_id = ext.finprod_id left join MST_TRADE_CALENDAR mtc on vfp.calendar_id=mtc.trade_calendar_id left join MST_CALENDAR_INFO mci on mtc.calendar_id=mci.calendar_id
AND vfp.finprod_type = #{finprodType}
AND (vfp.finprod_abbr like '%' || #{search} || '%' OR vfp.finprod_id like '%' || #{search} || '%' )
AND vfp.finprod_id in
#{item}
AND type.type_1 in
#{item}
AND vfp.issuer like '%' || #{issuer} || '%'

    	select SEQ_NO seqNo
    	from SYS_DATA_PROCESS_MARK pm
    	inner join () tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID

    			pm.status in ('A','U','P')

	            	and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


					and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


					and pm.BUSINESS_DATA_PK3 = #{businessDataPk3}


					and pm.BUSINESS_DATA_PK4 = #{businessDataPk4}


					and pm.BUSINESS_DATA_PK5 = #{businessDataPk5}


					and pm.BUSINESS_DATA_PK6 = #{businessDataPk6}


					and pm.BUSINESS_DATA_PK7 = #{businessDataPk7}


					and pm.BUSINESS_DATA_PK8 = #{businessDataPk8}


					and pm.BUSINESS_DATA_PK9 = #{businessDataPk9}


					and pm.BUSINESS_DATA_PK10 = #{businessDataPk10}

mapper.sql:
    	select 
			max(HIS_NO)	       HIS_NO,
			WORKFLOW_ID
         from SYS_DATA_PROCESS_MARK


	            	and BUSINESS_DATA_PK1 = #{businessDataPk1}


					and BUSINESS_DATA_PK2 = #{businessDataPk2}


					and BUSINESS_DATA_PK3 = #{businessDataPk3}


					and BUSINESS_DATA_PK4 = #{businessDataPk4}


					and BUSINESS_DATA_PK5 = #{businessDataPk5}


					and BUSINESS_DATA_PK6 = #{businessDataPk6}


					and BUSINESS_DATA_PK7 = #{businessDataPk7}


					and BUSINESS_DATA_PK8 = #{businessDataPk8}


					and BUSINESS_DATA_PK9 = #{businessDataPk9}


					and BUSINESS_DATA_PK10 = #{businessDataPk10}


			group by  WORKFLOW_ID
